"""Static reading companion and launch points for the interactive practice studio."""

def add_studio(lesson, section, note, table):
    lesson("studio", "Practise with pictures and buttons", 40,
      "Watch a file change, choose where a branch moves, and work through a mistake. Each choice explains its result.",
      ["Predict which content a command will record.", "Read a history picture and choose which commit a branch will point to.", "Choose a fix after reading the facts, then retry difficult questions."], [
      section("choose", "Choose a practice station", """
<div class="studio-intro">
  <div><p class="eyebrow">Learn by changing the picture</p><h3>Predict. Try. Explain. Repeat.</h3><p>Start with one station. Notice what moves and what stays. Say why the result makes sense before moving on.</p><p class="meta">No timer, no lost lives. Every mistake comes with a reason.</p><p id="studio-progress" role="status">Five stations · fourteen practice goals</p></div>
  <svg viewBox="0 0 340 230" role="img" aria-labelledby="studio-map-title"><title id="studio-map-title">Your learning path branches into practice and rejoins with stronger recall</title><path d="M35 115H105L185 45H290M105 115L185 185H290M105 115H290" fill="none" stroke="currentColor" stroke-width="3"/><g fill="var(--surface)" stroke="currentColor" stroke-width="3"><circle cx="35" cy="115" r="12"/><circle cx="105" cy="115" r="12"/><circle cx="185" cy="45" r="12"/><circle cx="185" cy="115" r="12"/><circle cx="185" cy="185" r="12"/><circle cx="290" cy="45" r="12"/><circle cx="290" cy="115" r="12"/><circle cx="290" cy="185" r="12"/></g><g fill="var(--text)" font-size="13" font-family="system-ui"><text x="15" y="150">learn</text><text x="159" y="22">predict</text><text x="169" y="151">try</text><text x="157" y="218">explain</text></g></svg>
</div>
<nav class="station-menu" aria-label="Practice stations">
 <a href="#snapshots"><span class="station-number">01</span><b>File and staging lab</b><small>Move file versions · 6 min</small></a>
 <a href="#pointers"><span class="station-number">02</span><b>Move the branch name</b><small>Predict six histories · 8 min</small></a>
 <a href="#incidents"><span class="station-number">03</span><b>Work through a mistake</b><small>Read facts → choose a fix · 10 min</small></a>
 <a href="#match"><span class="station-number">04</span><b>Connect the command</b><small>Match eight tasks · 5 min</small></a>
 <a href="#sprint"><span class="station-number">05</span><b>Five-minute recall</b><small>Try to remember, then retry · 5 min</small></a>
</nav>""" + note("Practice model", "The studio changes browser models only. It does not run Git or touch a repository. The <a href=\"practice.html\">real Git labs</a> let you verify the same ideas in a terminal. Completed goals and recall results use your existing exportable learning progress.")),
      section("snapshots", "01 · Watch a saved version move",
        '<p>One file can have different text in your editor, in staging, and in the current saved commit. Change the working file, stage its current content, then commit. Each lane shows the actual content held in that part of this model.</p><div id="snapshot-studio" class="studio-tool"></div><noscript><p>Example: HEAD has base text. Edit to version A, stage A, then edit to B. Staging still holds A. Commit records A and leaves B as an unstaged edit. Unstaging restores the current saved content in staging; it does not discard the working file.</p></noscript>'),
      section("pointers", "02 · Where does the branch go?",
        '<p>Read the operation and move the branch badge to its resulting commit. Dragging is optional: tap or keyboard-select a commit, then check. Dashed circles are possible new commits for this prediction.</p><div id="pointer-studio" class="studio-tool"></div><noscript><p>Fast-forward moves the branch name to an existing later commit in the same history. A true merge moves to a new two-parent commit. Rebase makes new commits by applying changes again, and moves that branch. Revert adds a commit that reverses a chosen change. Soft reset moves the branch but keeps staged and working content. Fetch normally updates your local records of remote branches, not your checked-out local branch.</p></noscript>'),
      section("incidents", "03 · You are on call for the repository",
        '<p>Open the evidence cards, choose the next step, and explain the outcome. A wrong choice stays at the current step so you can learn from its consequence.</p><div id="incident-studio" class="studio-tool"></div><noscript><p>Rejected push: fetch and check the separate new commits on both sides, combine the teammate’s change, then test and push normally. Lost committed work: check reflog, keep the found commit with a rescue branch, then choose how to bring the work back. Rebase conflict: check the change being applied now and all available stages, keep intended behavior, stage, test and continue.</p></noscript>'),
      section("match", "04 · Connect a task to a command",
        '<p>Choose one task and its matching command. Work from the effect you need. Both columns stay visible: the challenge is understanding the match, not guessing where a card was hidden.</p><div id="match-studio" class="studio-tool"></div><noscript><p>Use the <a href="reference.html">task-to-command table</a>: cover the command column, say your answer, then uncover it.</p></noscript>'),
      section("sprint", "05 · A small recall round",
        '<p>Five questions, about five minutes, without a countdown. Previously missed studio questions come first. Make a prediction before reading the explanation, then retry the questions you missed. These answers are separate from your full quiz attempt.</p><div id="recall-studio" class="studio-tool"></div><noscript><p>Choose five prompts from the <a href="quiz.html">readable question bank</a>. Write your answers, check the explanations, then repeat the missed prompts without looking.</p></noscript>'),
      section("transfer", "Turn the picture into a lasting explanation",
        table(["Picture", "Say this from memory", "Verify in a real lab"], [
          ["Three file-content boxes", "Add copies current content into the staging area. Commit records the staging area.", '<a href="practice.html#staging">Staging lab</a>'],
          ["A commit with two parents", "Merge keeps both earlier-commit links; the final behavior still needs tests.", '<a href="practice.html#three-way">Three-way merge lab</a>'],
          ["A moved branch badge", "A branch name moved. Ask what stayed available through a saved name and what happened to the files.", '<a href="practice.html#reflog">Reflog recovery lab</a>'],
          ["A rejected lease", "The server’s last commit differs from the ID I expected. Check the new work.", '<a href="practice.html#lease">Alice/Bob push race</a>']
        ]) + '<p>Tomorrow, return for another recall round. Later, use the <a href="recap.html">scheduled recall cards</a> and explain one incident to a teammate. A completed badge records practice, not a guarantee of real-world skill.</p>')
    ], ["Say whether you need to change your file, staging, or saved history.", "Predict where the branch will point and which earlier commits it will include.", "Use mistakes as a shortlist for your next recall session."])
